design_text:
{
  "site_summary": "A full sun balcony with moderate moisture and no pets in the household, designed as a fragrant sensory herb garden.",
  "layout_strategy": "The scheme is structured in three distinct vertical layers starting with trailing fragrant herbs spilling over the railing at eye level, rising to upright architectural herb shrubs in containers at mid-height against the back wall, and finished with a low ground-level tray of aromatic groundcover along the floor edge.",
  "combination_logic": "The plants work together through a harmonious contrast of fine needle-like foliage, broad soft leaves, and woody stems, combining strong aromatic scents of mint, lavender, and thyme. The visual composition layers silver-grey tones against deep greens, while the seasonal rhythm brings spring flushes of growth, summer peak flowering for pollinators, and evergreen structure in winter.",
  "zones": [
    {
      "zone_name": "Railing Cascade",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "On the south-facing balcony railing, receiving full sun all day with high exposure to wind and heat.",
      "plants": [
        {
          "scientific_name": "Thymus serpyllum",
          "common_name": "Creeping Thyme",
          "why": "It loves full sun and naturally cascades over container edges, tolerating the exposed railing conditions.",
          "role_in_combination": "Contributes a fine-textured, carpet-like green trail with tiny purple summer flowers that contrast against larger leaf shapes nearby."
        },
        {
          "scientific_name": "Origanum vulgare",
          "common_name": "Trailing Oregano",
          "why": "Spills gracefully and thrives in baking sun.",
          "role_in_combination": "Adds a looser, brighter green hanging habit that softens the rigid lines of the balcony railing."
        }
      ],
      "maintenance": [
        "Water daily during peak summer heat as hanging baskets dry out rapidly.",
        "Feed with a liquid organic fertilizer once a month in spring and summer.",
        "Prune back lightly after flowering to encourage dense new growth.",
        "Repot every two years in fresh, well-draining gritty compost."
      ]
    },
    {
      "zone_name": "Mid-Level Architectural Wall",
      "zone_role": "screening",
      "layer": "mid",
      "placement": "Against the back interior wall of the balcony in large containers, receiving intense direct sunlight for over 6 hours a day.",
      "plants": [
        {
          "scientific_name": "Rosmarinus officinalis",
          "common_name": "Rosemary",
          "why": "Provides height, structure, and intense fragrance while loving dry, sunny conditions.",
          "role_in_combination": "Acts as the structural anchor with woody vertical stems and needle-like dark green leaves that provide year-round height contrast."
        },
        {
          "scientific_name": "Lavandula angustifolia",
          "common_name": "English Lavender",
          "why": "Brings striking floral spikes and silvery foliage that thrive in baked spots.",
          "role_in_combination": "Introduces a contrasting cool silver foliage color and vibrant purple summer flower spikes that elevate the sensory experience."
        }
      ],
      "maintenance": [
        "Water deeply once a week once established, allowing soil to dry slightly between waterings.",
        "Feed lightly in early spring with a slow-release organic fertilizer.",
        "Prune hard after flowering in late summer, cutting back to soft green growth but never into old bare wood.",
        "Repot into larger containers every spring if root-bound."
      ]
    },
    {
      "zone_name": "Floor Level Sensory Patch",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "In a wide, shallow wooden trough on the balcony floor near the entrance, getting full overhead sun.",
      "plants": [
        {
          "scientific_name": "Mentha spicata",
          "common_name": "Spearmint",
          "why": "Contained safely in a low trough to prevent aggressive spreading, offering wonderful tactile and aromatic qualities.",
          "role_in_combination": "Contributes lush, bright green broad leaves and a refreshing scent that contrasts sharply with the needle-like foliage of the rosemary."
        }
      ],
      "maintenance": [
        "Keep consistently moist, watering every two days in summer as mint hates drying out.",
        "Cut back entirely to the soil level in late autumn to encourage fresh spring flushes.",
        "Divide the root ball every spring to keep the plant vigorous and contained within the trough."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers with a finger test before watering.",
      "frequency": "Daily in summer, twice a week in spring and autumn.",
      "season": "Summer and Spring"
    },
    {
      "task": "Apply organic liquid kelp fertilizer to all mid-level and hanging containers to support continuous herb growth.",
      "frequency": "Every two weeks.",
      "season": "Spring and Summer"
    },
    {
      "task": "Inspect foliage and stems for aphids or spider mites which thrive in hot, dry balcony conditions.",
      "frequency": "Weekly.",
      "season": "Summer"
    }
  ],
  "care_cautions": [
    "Overwatering and root rot in the hanging baskets can occur if drainage holes are blocked or if they are watered excessively during cooler, overcast spring days.",
    "Scorch on the hot south-facing wall can stress the lavender and rosemary if they transition too quickly from a dark nursery to intense, reflective balcony sun without gradual hardening off.",
    "Poor drainage in the floor-level mint trough can lead to stagnant water and root decay if excess runoff collects in a saucer below."
  ],
  "pet_safety_note": "Although no pets currently live in the household, the herbs selected are generally safe, and the layout avoids toxic ornamental plants."
}
